/* Every name xdg-user-dirs has given the public share folder
 * (XDG_PUBLICSHARE_DIR), in every language, through the whole history of
 * its translations: what the project knows, besides what the catalogs
 * installed on the machine say. Generated by tools/xdg-public-names.py into
 * xdg-public-names.c. */
#pragma once

typedef struct {
    const char *lang;        /* the catalog's language ("nb", "sr@latin"); "" for English */
    const char *name;        /* the folder's name, UTF-8 */
    const char *first_seen;  /* when the name came into the translation, YYYY-MM-DD */
    int current;             /* the name the translation has today */
} gaudit_xdg_public_name;

extern const gaudit_xdg_public_name gaudit_xdg_public_names[];
extern const unsigned gaudit_xdg_public_names_count;
